const API_BASE = import.meta.env.VITE_API_BASE || '/api';
const CALC_AVG_MARGIN_PCT = 18;

const resolveImageUrl = (url) => {
  if (!url || typeof url !== 'string') return null;
  const trimmed = url.trim();
  if (!trimmed) return null;
  if (trimmed.startsWith('http') || trimmed.startsWith('data:')) return trimmed;
  if (trimmed.startsWith('/api/')) {
    const base = API_BASE.replace(/\/api\/?$/, '');
    return `${base}${trimmed}`;
  }
  const sep = (API_BASE.endsWith('/') || trimmed.startsWith('/')) ? '' : '/';
  return `${API_BASE}${sep}${trimmed}`;
};

const ProductImage = ({ src, alt, style, t, className, containerStyle }) => {
  const [hasError, setHasError] = useState(false);
  const resolved = resolveImageUrl(src);

  useEffect(() => {
    setHasError(false);
  }, [src]);

  if (!resolved || hasError) {
    return (
      <div
        className={className}
        style={{
          width: style?.width || '100%',
          height: style?.height || '100%',
          borderRadius: style?.borderRadius || '6px',
          backgroundColor: 'var(--surface-overlay)',
          color: 'var(--text-muted)',
          display: 'flex',
          alignItems: 'center',
          justifyContent: 'center',
          fontSize: '0.65rem',
          textAlign: 'center',
          padding: '0.2rem',
          userSelect: 'none',
          boxSizing: 'border-box',
          flexShrink: style?.flexShrink !== undefined ? style.flexShrink : 0,
          ...containerStyle
        }}
      >
        <span>{t ? t('No photo', 'कोई फ़ोटो नहीं', 'ছবি নেই') : 'No photo'}</span>
      </div>
    );
  }

  return (
    <img
      src={resolved}
      alt={alt || ''}
      className={className}
      style={style}
      onError={() => setHasError(true)}
    />
  );
};

const isWithinOpeningHours = (profile) => {
  if (!profile.opening_time || !profile.closing_time) return true;
  const now = new Date();
  const cur = `${String(now.getHours()).padStart(2,'0')}:${String(now.getMinutes()).padStart(2,'0')}`;
  const { opening_time: o, closing_time: c } = profile;
  return c <= o ? (cur >= o || cur < c) : (cur >= o && cur < c);
};

const originalFetch = window.fetch;
window.fetch = async (...args) => {
  const [resource, config] = args;
  let tokenAttached = false;

  if (typeof resource === 'string' && resource.includes(API_BASE)) {
    const token = (() => { try { return localStorage.getItem('token'); } catch { return null; } })();
    if (token) {
      args[1] = config || {};
      args[1].headers = {
        ...args[1].headers,
        'Authorization': `Bearer ${token}`
      };
      tokenAttached = true;
    }
  }

  const res = await originalFetch(...args);
  if (
    res.status === 401 &&
    tokenAttached &&
    typeof resource === 'string' &&
    resource.includes(API_BASE) &&
    !resource.includes('/auth/login') &&
    !resource.includes('/auth/verify') &&
    !resource.includes('/auth/setup-complete') &&
    !resource.includes('/auth/me')
  ) {
    window.dispatchEvent(new CustomEvent('session-expired'));
  }
  return res;
};
const normalizeFrontendPhone = (val) => {
  if (!val) return '';
  let str = String(val);
  let clean = str.replace(/\D/g, '');
  if (str.trim().startsWith('+91') || str.trim().startsWith('91 ') || (clean.length === 12 && clean.startsWith('91'))) {
    clean = clean.slice(2);
  } else if (clean.length > 10 && clean.startsWith('91')) {
    clean = clean.slice(2);
  }
  return clean.slice(0, 10);
};

