const asList = (res, data, fallback = []) => (res && res.ok && Array.isArray(data) ? data : fallback);

// The backend accepts two spellings of the same order stages (RECEIVED/READY and
// ACCEPTED/PREPARING/READY_FOR_PICKUP/OUT_FOR_DELIVERY). The UI works with one
// set, so orders are mapped onto it as they arrive from the API.
const UI_ORDER_STATUS = { ACCEPTED: 'RECEIVED', PREPARING: 'RECEIVED', READY_FOR_PICKUP: 'READY', OUT_FOR_DELIVERY: 'READY' };
const toUiOrder = (o) => (o && UI_ORDER_STATUS[o.status] ? { ...o, status: UI_ORDER_STATUS[o.status] } : o);
const toUiOrders = (list) => (Array.isArray(list) ? list.map(toUiOrder) : list);
const plural = (n, one, many) => (Number(n) === 1 ? one : many);

// reCAPTCHA v3 loads only when a real site key is configured. Without one
// (local development) the backend skips CAPTCHA checks outside production.
const RECAPTCHA_SITE_KEY = import.meta.env.VITE_RECAPTCHA_SITE_KEY || '';
let recaptchaLoad = null;
const loadRecaptcha = () => {
  if (!RECAPTCHA_SITE_KEY) return Promise.resolve(null);
  if (!recaptchaLoad) {
    recaptchaLoad = new Promise((resolve) => {
      const script = document.createElement('script');
      script.src = `https://www.google.com/recaptcha/api.js?render=${encodeURIComponent(RECAPTCHA_SITE_KEY)}`;
      script.async = true;
      script.onload = () => window.grecaptcha.ready(() => resolve(window.grecaptcha));
      script.onerror = () => { recaptchaLoad = null; resolve(null); };
      document.head.appendChild(script);
    });
  }
  return recaptchaLoad;
};

class PanelErrorBoundary extends React.Component {
  constructor(props) {
    super(props);
    this.state = { hasError: false, error: null };
  }
  static getDerivedStateFromError(error) {
    return { hasError: true, error };
  }
  componentDidCatch(error, errorInfo) {
    console.error("PanelErrorBoundary caught an error:", error, errorInfo);
  }
  render() {
    if (this.state.hasError) {
      const t = this.props.t || ((en, hi, bn) => en);
      return (
        <div style={{ padding: '2rem', background: 'var(--danger-bg)', border: '1px solid var(--danger)', borderRadius: '8px', color: 'var(--danger-text)', margin: '1rem 0' }}>
          <h3 style={{ marginBottom: '0.5rem' }}>{t('Unable to load panel', 'पैनल लोड करने में असमर्थ', 'প্যানেল লোড করতে অক্ষম')}</h3>
          <p style={{ fontSize: '0.85rem', color: 'var(--text-muted)', marginBottom: '1rem' }}>
            {t('An unexpected error occurred while rendering this view', 'यह दृश्य प्रस्तुत करते समय एक अप्रत्याशित त्रुटि हुई', 'এই ভিউ রেন্ডার করার সময় একটি অপ্রত্যাশিত ত্রুটি ঘটেছে')} ({this.state.error?.message || t('Unknown error', 'अज्ञात त्रुटि', 'অজানা ত্রুটি')}).
          </p>
          <div style={{ display: 'flex', gap: '1rem' }}>
            <button className="btn btn-secondary" onClick={() => this.setState({ hasError: false, error: null })}>
              {t('Try Again', 'पुनः प्रयास करें', 'আবার চেষ্টা করুন')}
            </button>
            <button className="btn btn-primary" onClick={() => window.location.reload()}>
              {t('Reload', 'पुनः लोड करें', 'রিলোড করুন')}
            </button>
          </div>
        </div>
      );
    }
    return this.props.children;
  }
}

// Center-crop to square, scale to `size`, return a compressed JPEG/WebP Blob
function resizeImageToSquare(file, size = 512, quality = 0.85) {
  return new Promise((resolve, reject) => {
    const url = URL.createObjectURL(file);
    const img = new window.Image();
    img.onload = () => {
      const side = Math.min(img.width, img.height);      // largest centered square that fits
      const sx = (img.width - side) / 2;
      const sy = (img.height - side) / 2;
      const target = Math.min(size, side < size ? size : size); // never upscale beyond `size`; small imgs fill to size
      const canvas = document.createElement('canvas');
      canvas.width = size;
      canvas.height = size;
      const ctx = canvas.getContext('2d');
      ctx.imageSmoothingQuality = 'high';
      ctx.drawImage(img, sx, sy, side, side, 0, 0, size, size);
      URL.revokeObjectURL(url);
      canvas.toBlob(
        blob => blob ? resolve({ blob, previewUrl: URL.createObjectURL(blob) }) : reject(new Error('resize-failed')),
        'image/jpeg',
        quality
      );
    };
    img.onerror = () => { URL.revokeObjectURL(url); reject(new Error('bad-image')); };
    img.src = url;
  });
}

