const AppSplash = ({ theme, onDone, role }) => {
  const [out, setOut] = React.useState(false);
  const lockupRef = React.useRef(null);
  const coinRef = React.useRef(null);
  const roleRef = React.useRef(null);

  React.useEffect(() => {
    if (!role) return;

    const measure = () => {
      const lock = lockupRef.current, coin = coinRef.current, roleEl = roleRef.current;
      if (!lock || !coin || !roleEl) return false;
      const ci = coin.offsetParent;
      if (!ci) return false;
      let wordLeft = 0, wordTop = 0;
      if (ci.offsetParent && ci.offsetParent !== lock) {
        wordLeft = ci.offsetParent.offsetLeft;
        wordTop = ci.offsetParent.offsetTop;
      }
      const x0 = wordLeft + ci.offsetLeft + coin.offsetLeft + coin.offsetWidth / 2;
      const y0 = wordTop + ci.offsetTop + coin.offsetTop + coin.offsetHeight / 2;
      const x1 = roleEl.offsetLeft + roleEl.offsetWidth / 2;
      const y1 = roleEl.offsetTop + roleEl.offsetHeight / 2;
      const ok = [x0, y0, x1, y1].every(Number.isFinite) && x0 > 0 && y1 > y0 && lock.offsetWidth > 0;
      if (!ok) return false;
      lock.style.setProperty('--x0', `${x0}px`);
      lock.style.setProperty('--y0', `${y0}px`);
      lock.style.setProperty('--x1', `${x1}px`);
      lock.style.setProperty('--y1', `${y1}px`);
      const dx = lock.querySelector('.cs-dropx');
      if (dx) dx.style.transform = `translateX(${x0}px)`;
      return true;
    };

    const rafId = window.requestAnimationFrame(() => {
      measure();
    });
    let anims = [];
    const timerId = setTimeout(() => {
      const ok = measure();
      const lock = lockupRef.current;
      if (!lock) return;
      if (!ok) { lock.classList.add('cs-nodrop'); return; }
      if (window.matchMedia('(prefers-reduced-motion: reduce)').matches) return;
      const cs = window.getComputedStyle(lock);
      const x0 = parseFloat(cs.getPropertyValue('--x0')), y0 = parseFloat(cs.getPropertyValue('--y0'));
      const x1 = parseFloat(cs.getPropertyValue('--x1')), y1 = parseFloat(cs.getPropertyValue('--y1'));
      const dx = lock.querySelector('.cs-dropx'), dy = lock.querySelector('.cs-dropy'), sp = lock.querySelector('.cs-splat');
      anims.push(dx.animate([{ transform: `translateX(${x0}px)` }, { transform: `translateX(${x1}px)` }], { duration: 420, delay: 40, easing: 'linear', fill: 'forwards' }));
      anims.push(dy.animate([
        { offset: 0, opacity: 0, transform: `translateY(${y0}px) scale(0.4)`, easing: 'cubic-bezier(0.5, 0, 1, 0.6)' },
        { offset: 0.12, opacity: 1, transform: `translateY(${y0}px) scale(1, 1.15)`, easing: 'cubic-bezier(0.5, 0, 1, 0.6)' },
        { offset: 1, opacity: 1, transform: `translateY(${y1}px) scale(0.9, 1.25)` }
      ], { duration: 420, delay: 40, fill: 'forwards' }));
      anims.push(dy.animate([{ opacity: 1 }, { opacity: 0 }], { duration: 1, delay: 480, fill: 'forwards' }));
      anims.push(sp.animate([
        { opacity: 0.9, transform: `translateX(${x1}px) translateY(${y1}px) scale(1)` },
        { opacity: 0, transform: `translateX(${x1}px) translateY(${y1}px) scale(5, 2.2)` }
      ], { duration: 520, delay: 460, easing: 'ease-out', fill: 'forwards' }));
    }, 1080);

    return () => {
      window.cancelAnimationFrame(rafId);
      clearTimeout(timerId);
      anims.forEach(a => a.cancel());
    };
  }, [role]);

  React.useEffect(() => {
    const reduced = window.matchMedia('(prefers-reduced-motion: reduce)').matches;
    const dur = role ? 2300 : 1900;
    const animDur = reduced ? 700 : dur;
    
    let t0;
    if (role && !reduced && lockupRef.current) {
      t0 = setTimeout(() => {
        if (lockupRef.current) lockupRef.current.classList.add('cs-landed');
      }, 1560);
    }
    
    const t1 = setTimeout(() => setOut(true), animDur);
    const t2 = setTimeout(onDone, animDur + 300);
    return () => { clearTimeout(t0); clearTimeout(t1); clearTimeout(t2); };
  }, [role]); // Removing onDone to prevent timer reset if parent re-renders

  const skip = () => { setOut(true); setTimeout(onDone, 300); };
  const letters = ['b', 'e', 'n', null, 'f', 'f', 'y'];
  
  const word = (
    <div className="cs-word">
      {letters.map((ch, i) => ch ? (
        <span key={i} className="cs-ch" style={{ '--i': i }}>{ch}</span>
      ) : (
        <span key={i} className="cs-ch cs-i" style={{ '--i': i }}>ı<span className="cs-ring"></span><span ref={coinRef} className="cs-coin"></span></span>
      ))}
    </div>
  );

  return (
    <div className={`cs-splash ${out ? 'cs-out' : ''}`} data-theme={theme} onClick={skip} role="presentation" aria-hidden="true">
      {role ? (
        <div className="cs-lockup" ref={lockupRef}>
          {word}
          <div className="cs-role" ref={roleRef}>{role}</div>
          <div className="cs-dropx"><div className="cs-dropy"></div></div>
          <div className="cs-splat"></div>
        </div>
      ) : (
        <>
          {word}
          <div className="cs-tag">Shop local. Pay less for everything else.</div>
        </>
      )}
    </div>
  );
};


